import { createRequestHandler } from "react-router";
import { isProtectedResourceReentry } from "@webstudio-is/sdk/protected-resource-fetch";
// @ts-ignore - generated by the Webstudio CLI at build time
import { projectId } from "../app/__generated__/_index";

declare module "react-router" {
  export interface AppLoadContext {
    cloudflare: {
      env: Env;
      ctx: ExecutionContext;
    };
  }
}

const requestHandler = createRequestHandler(
  // @ts-ignore
  () => import("virtual:react-router/server-build"),
  import.meta.env.MODE
);

export default {
  async fetch(request, env, ctx) {
    if (isProtectedResourceReentry(request, projectId)) {
      return new Response(null, { status: 508 });
    }
    return requestHandler(request, {
      EXCLUDE_FROM_SEARCH: false,
      cloudflare: { env, ctx },
    });
  },
} satisfies ExportedHandler<Env>;
